Here is the reliable, debounced button sketch using internal pull-up:

```cpp
#include <Arduino.h>

const int BUTTON_PIN = 2;
const int LED_PIN = 13;

int lastButtonState = HIGH;
unsigned long lastDebounceTime = 0;
const unsigned long DEBOUNCE_DELAY = 50; // 50ms debounce window

void setup() {
  Serial.begin(115200);
  pinMode(BUTTON_PIN, INPUT_PULLUP); // Active LOW: HIGH=released, LOW=pressed
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
}

void loop() {
  int reading = digitalRead(BUTTON_PIN);

  // Reset debounce timer on state transition
  if (reading != lastButtonState) {
    lastDebounceTime = millis();
    lastButtonState = reading;
  }

  if ((millis() - lastDebounceTime) > DEBOUNCE_DELAY) {
    if (reading == LOW) {
      digitalWrite(LED_PIN, HIGH); // Button is pressed
    } else {
      digitalWrite(LED_PIN, LOW);  // Button is released
    }
  }
}
```

